insert into public.quizzes(id,slug,title_kn,title_en,title_hi,questions,status,is_seed) values('2dc86f6a-cae5-4be5-8835-06c7ae735d45','reading-demo','ಓದುವ ಅನುಭವ — ಮಾದರಿ ರಸಪ್ರಶ್ನೆ','The Reading Experience — Sample Quiz','पठन अनुभव — नमूना प्रश्नोत्तरी','[{"question":"ಸುದ್ದಿಯನ್ನು ನಂತರ ಓದಲು ಯಾವ ಆಯ್ಕೆ ಬಳಸಬೇಕು?","question_en":"Which option should you use to read a news item later?","question_hi":"समाचार को बाद में पढ़ने के लिए किस विकल्प का उपयोग करें?","options":["ಉಳಿಸಿ","ಹುಡುಕಿ","ಹಂಚಿಕೊಳ್ಳಿ"],"options_en":["Save","Search","Share"],"options_hi":["सहेजें","खोजें","साझा करें"],"answer":0,"explanation":"ಉಳಿಸಿ ಆಯ್ಕೆ ಲೇಖನವನ್ನು ಮತ್ತೆ ತೆರೆಯಲು ಸಹಾಯ ಮಾಡುತ್ತದೆ.","explanation_en":"The Save option lets you open the article again later.","explanation_hi":"सहेजें विकल्प लेख को बाद में दोबारा खोलने में मदद करता है।"},{"question":"ಕಾರ್ಯಕ್ರಮಕ್ಕೆ ಹೋಗುವ ಮೊದಲು ಏನು ದೃಢಪಡಿಸಬೇಕು?","question_en":"What should you confirm before attending an event?","question_hi":"कार्यक्रम में जाने से पहले किसकी पुष्टि करनी चाहिए?","options":["ಚಿತ್ರದ ಬಣ್ಣ","ದಿನಾಂಕ ಮತ್ತು ಸ್ಥಳ","ಪುಟದ ಗಾತ್ರ"],"options_en":["The colour of the photo","The date and the venue","The size of the page"],"options_hi":["चित्र का रंग","तारीख और स्थान","पृष्ठ का आकार"],"answer":1,"explanation":"ದಿನಾಂಕ ಮತ್ತು ಸ್ಥಳವನ್ನು ಆಯೋಜಕರಿಂದ ದೃಢಪಡಿಸಿಕೊಳ್ಳಿ.","explanation_en":"Confirm the date and the venue with the organisers.","explanation_hi":"तारीख और स्थान आयोजकों से पुष्ट कर लें।"}]','published',true) on conflict do nothing;
insert into public.topics(id,slug,title_kn,intro_kn,title_en,intro_en,title_hi,intro_hi,cover_url,key_facts,key_facts_en,key_facts_hi,tag_ids,timeline,event_ids,liveblog_post_id,is_active,sort_order) values('72d2dcac-34fe-406a-8d8b-45ed50e2d9c3','jain-heritage','ನಮ್ಮ ಜೈನ ಪರಂಪರೆ','ಬಸದಿಗಳು, ಇತಿಹಾಸ ಮತ್ತು ಸಂಸ್ಕೃತಿಯ ಕುರಿತ ಮಾದರಿ ವರದಿಗಳ ಸಂಗ್ರಹ.','Our Jain Heritage','A collection of sample reports on Basadis, history and culture.','हमारी जैन परंपरा','बसदियों, इतिहास और संस्कृति पर आधारित नमूना रिपोर्टों का संग्रह।','/images/temple.webp','["ಮಾದರಿ ವಿಷಯಗಳ ಸಂಗ್ರಹ","ಸಂಬಂಧಿತ ಸುದ್ದಿಗಳು ಮತ್ತು ಕಾರ್ಯಕ್ರಮಗಳು"]','["A collection of sample topics","Related news and events"]','["नमूना विषयों का संग्रह","संबंधित समाचार और कार्यक्रम"]',ARRAY['396733d0-a1de-4262-8e10-6a771334b795']::uuid[],'[{"date":"2026-09-14","text":"ಪರಂಪರೆ ಪರಿಚಯ — ಮಾದರಿ ವರದಿ","text_en":"An Introduction to Our Heritage — Sample Report","text_hi":"परंपरा का परिचय — नमूना रिपोर्ट"}]',ARRAY['00000000-0000-4000-8000-000000000100']::uuid[],null,true,0) on conflict do nothing;
insert into public.topics(id,slug,title_kn,intro_kn,title_en,intro_en,title_hi,intro_hi,cover_url,key_facts,key_facts_en,key_facts_hi,tag_ids,timeline,event_ids,liveblog_post_id,is_active,sort_order) values('8dfcea33-5247-45f6-896a-7fc0133c54e4','chaturmasa-2026','ಚಾತುರ್ಮಾಸ 2026','ಪ್ರವಚನ, ಆತ್ಮಚಿಂತನೆ ಮತ್ತು ಸಮುದಾಯದ ಕಾರ್ಯಕ್ರಮಗಳ ಮಾದರಿ ಸಂಗ್ರಹ.','Chaturmasa 2026','A sample collection of discourses, self-reflection and community programmes.','चातुर्मास 2026','प्रवचन, आत्मचिंतन और समुदाय के कार्यक्रमों का नमूना संग्रह।','/images/detail.webp','["ಮಾದರಿ ಮಾಹಿತಿ — ಪ್ರಕಟಣೆಗೆ ಮೊದಲು ಸಂಪಾದಕೀಯ ಪರಿಶೀಲನೆ ಅಗತ್ಯ."]','["Sample information — editorial review required before publication."]','["नमूना जानकारी — प्रकाशन से पहले संपादकीय समीक्षा आवश्यक।"]',ARRAY['87d59789-6cb9-49a4-82fb-69cd5c38d606','08f4d3c4-47c4-47e1-86f0-7490a6bf6263']::uuid[],'[]',ARRAY[]::uuid[],'351159c0-b921-4062-87d6-6c668a3b2a0b',true,1) on conflict do nothing;
